from typing import FrozenSet, Iterator

def subsets(u: tuple[int, ...]) -> Iterator[FrozenSet[int]]:
    for r in range(len(u) + 1):
        for c in combinations(u, r):
            yield frozenset(c)

def main() -> None:
    u = tuple(range(9))
    family = [frozenset({0,1,2}), frozenset({1,2,3}), frozenset({0,1,2,3})]
    exact = sum(any(t <= s for t in family) for s in subsets(u))
    bound = sum(2 ** (len(u) - len(t)) for t in family)
    print({"exact_bad_count": exact, "union_bound": bound, "overlap_saving": bound-exact})
    assert exact <= bound

if __name__ == "__main__":
    main()

from itertools import combinations
from typing import FrozenSet, Iterable, Optional

def find_witness(u: FrozenSet[int], forbidden: Iterable[FrozenSet[int]], d: int) -> Optional[FrozenSet[int]]:
    f = tuple(forbidden)
    ordered = sorted(u)
    for r in range(d, len(ordered) + 1):
        for c in combinations(ordered, r):
            s = frozenset(c)
            if all(not t <= s for t in f):
                return s
    return None

def main() -> None:
    u = frozenset(range(13))
    pairs = [({0,1,2},{0,1,2}), ({1,2,3},{2,3,4}), ({0,2,4},{1,3,5})]
    forbidden = [frozenset(a+b for a in A for b in B) for A,B in pairs]
    witness = find_witness(u, forbidden, 3)
    print(sorted(witness) if witness else None)
    assert witness is not None and all(not t <= witness for t in forbidden)

if __name__ == "__main__":
    main()

