from typing import FrozenSet, Iterable

def integer_sumset(a: Iterable[int], b: Iterable[int]) -> FrozenSet[int]:
    return frozenset(x + y for x in a for y in b)

def deduplicated_cost(universe: FrozenSet[int], pairs: list[tuple[FrozenSet[int], FrozenSet[int]]]) -> int:
    sumsets = {integer_sumset(a, b) for a, b in pairs}
    if any(not t <= universe for t in sumsets):
        raise ValueError("sumset outside universe")
    return sum(2 ** (len(universe) - len(t)) for t in sumsets)

from itertools import combinations
from typing import FrozenSet, Optional

def exhaustive_dense_avoider(universe: FrozenSet[int], forbidden: list[FrozenSet[int]], d: int) -> Optional[FrozenSet[int]]:
    ordered = sorted(universe)
    for size in range(max(0, d), len(ordered) + 1):
        for choice in combinations(ordered, size):
            candidate = frozenset(choice)
            if all(not target <= candidate for target in forbidden):
                return candidate
    return None

